import app from "flarum/admin/app";
import LazyVerifiedSettingsPanel from "./components/LazyVerifiedSettingsPanel";
const EXT_ID = "ramon-verified";

/**
 * Wire the extension's admin UI: settings panel + the two permissions
 * surfaced in the standard PermissionGrid.
 *
 * Note: `verified.autoVerified` is NOT registered here. Auto-verification is
 * per-tier — each tier in Admin → Tiers picks the groups that get its badge
 * automatically.
 */
export default function addVerifiedSettingsPanel() {
  app.registry.for(EXT_ID).registerSetting(() => m(LazyVerifiedSettingsPanel, null), 100, "ramon-verified.panel").registerPermission({
    icon: "fas fa-certificate",
    label: app.translator.trans("ramon-verified.admin.permissions.request_label"),
    permission: "verified.request"
  }, "start").registerPermission({
    icon: "fas fa-user-check",
    label: app.translator.trans("ramon-verified.admin.permissions.verify_users_label"),
    permission: "verified.verifyUsers"
  }, "moderate").registerPermission({
    icon: "fas fa-ban",
    label: app.translator.trans("ramon-verified.admin.permissions.self_revoke_label"),
    permission: "verified.selfRevoke"
  }, "start");
}